import{_ as a,o as e,c as o,a5 as i}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"選択肢","description":"","frontmatter":{"title":"選択肢","order":7},"headers":[],"relativePath":"ja/2.4/tutorial/script/choice.md","filePath":"ja/2.4/tutorial/script/choice.md","lastUpdated":1788455378000}'),s={name:"ja/2.4/tutorial/script/choice.md"};function c(d,t,l,n,r,h){return e(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="選択肢ジャンプ" tabindex="-1">選択肢ジャンプ <a class="header-anchor" href="#選択肢ジャンプ" aria-label="Permalink to &quot;選択肢ジャンプ&quot;">​</a></h1><h2 id="機能概要" tabindex="-1">機能概要 <a class="header-anchor" href="#機能概要" aria-label="Permalink to &quot;機能概要&quot;">​</a></h2><p>この機能は<strong>分岐機能</strong>と組み合わせて使用する必要があります。主な役割は、インタラクティブな選択肢タグにジャンプロジックを設定することです。対応する選択肢をクリックすると、指定した分岐ノードへ直接ジャンプできます。各 <code>choice</code> 文は 1 つの選択肢を作成します。隣接する複数の <code>choice</code> 行は 1 つの選択肢グループにまとめられ、インタラクション時に同時に表示されます。</p><h2 id="構文" tabindex="-1">構文 <a class="header-anchor" href="#構文" aria-label="Permalink to &quot;構文&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;選択肢の内容&quot; -&gt; 分岐名</span></span></code></pre></div><table tabindex="0"><thead><tr><th>パラメーター</th><th>必須</th><th>例</th><th>説明</th></tr></thead><tbody><tr><td>選択肢の内容</td><td>はい</td><td>&quot;コーヒーを選ぶ&quot;</td><td>インタラクション時に表示される選択肢テキスト</td></tr><tr><td>分岐名</td><td>はい</td><td>coffee_choice</td><td>ジャンプ先分岐の一意な識別子</td></tr></tbody></table><h2 id="使用例" tabindex="-1">使用例 <a class="header-anchor" href="#使用例" aria-label="Permalink to &quot;使用例&quot;">​</a></h2><p>各選択肢を 1 行ずつ書く場合：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea</span></span>
<span class="line"><span>choice &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><p>複数の選択肢を 1 行に続けて書くこともできます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ol><li>分岐名はプロジェクト内で定義された分岐識別子と完全に一致する必要があります。大文字小文字を区別し、空白や特殊記号を含めることはできません。</li><li>選択肢の内容は英語の二重引用符で囲む必要があり、通常のテキスト文字を使用できます。</li><li><code>-&gt;</code> は選択肢と分岐名の区切り記号であり、省略できません。</li></ol>`,13)])])}const b=a(s,[["render",c]]);export{u as __pageData,b as default};
